contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other) public payable {
        require(other != address(this));

        uint256 balOtherBefore = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 balCallerBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.Collect(0); if (__ESBMC_reverted()) return;

        uint256 balOtherAfter = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 balCallerAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(balOtherAfter == balOtherBefore && balCallerAfter <= balCallerBefore);
    }

    receive() external payable {}
}

