pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(address other) internal {
        vm.assume(other != address(this));
        uint256 balOtherBefore;
        try c.balances(other) returns (uint256 __r) { balOtherBefore = __r; } catch { return; }
        uint256 balCallerBefore;
        try c.balances(address(this)) returns (uint256 __r) { balCallerBefore = __r; } catch { return; }
        try c.Collect(0) {} catch { return; }
        uint256 balOtherAfter;
        try c.balances(other) returns (uint256 __r) { balOtherAfter = __r; } catch { return; }
        uint256 balCallerAfter;
        try c.balances(address(this)) returns (uint256 __r) { balCallerAfter = __r; } catch { return; }
        assertTrue(balOtherAfter == balOtherBefore && balCallerAfter <= balCallerBefore);
    }

    function testFuzz_run(address other) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(other);
    }

    receive() external payable {}
}
